//go:build ignore

// Copy into upstream converter/musicxml and run TestCodexMusicXMLPitch.
package musicxml
import("encoding/json";"fmt";"math/rand";"os";"path/filepath";"testing";"github.com/shibukawa/tinygodriver/encoding/xmlro";"github.com/shibukawa/bdf/converter/internal/music")
func TestCodexMusicXMLPitch(t *testing.T){root:=os.Getenv("BDF_FIXTURE_ROOT");if root==""{t.Fatal("BDF_FIXTURE_ROOT required")};r:=rand.New(rand.NewSource(145120));steps:=[]string{"C","D","E","F","G","A","B","c","?",""};alters:=[]string{"","0","1","-1","2","-2","3","-4","4.5","-1.5","invalid"};octaves:=[]string{"","0","4","9","-1","10","-2","3.5","invalid"};accs:=[]string{"","sharp","flat","natural","double-sharp","quarter-sharp","koron","unknown"};ties:=[]string{"",`<tie type="start"/>`,`<tie type="stop"/>`,`<notations><tied type="continue"/></notations>`,`<tie type="stop"/><notations><tied type="start"/></notations>`,`<notations><technical><string>6</string><fret>17</fret></technical></notations>`,`<notations><technical><string>7</string><fret>5</fret></technical></notations>`};out:=[]any{}
 for i:=0;i<10000;i++ {a:=accs[r.Intn(len(accs))];acc:="";if a!=""{acc=fmt.Sprintf(`<accidental cautionary="%s">%s</accidental>`,[]string{"yes","no"}[r.Intn(2)],a)};src:=fmt.Sprintf(`<note><pitch><step>%s</step><alter>%s</alter><octave>%s</octave></pitch>%s%s<notehead>%s</notehead></note>`,steps[r.Intn(len(steps))],alters[r.Intn(len(alters))],octaves[r.Intn(len(octaves))],acc,ties[r.Intn(len(ties))],[]string{"","normal","x","cross"}[r.Intn(4)]);d:=newXMLReader([]byte(src));for{k,e:=d.Next();if e!=nil{t.Fatal(e)};if k==xmlro.StartElement{break}};n,e:=readNode(d);if e!=nil{t.Fatal(e)};reader:=newReader();p:=newPart("P1","");p.transpose=r.Intn(97)-48;st:=&mstate{pm:&music.PartMeasure{},play:&playMeasure{},tuplets:map[int]*tupletState{}};reader.note(p,st,n);v:=st.pm.Events[0].Notes[0];play:=st.play.notes[0];str,fret:=-1,-1;if v.Tab!=nil{str,fret=v.Tab.String,v.Tab.Fret};out=append(out,map[string]any{"input":[]byte(src),"transpose":p.transpose,"want":[]any{v.Pitch.Step,v.Pitch.Alter,v.Pitch.Octave,*v.SoundingMIDI,int(v.Accidental),v.Cautionary,int(v.Head),v.TieStart,v.TieStop,play.tieStart,play.tieStop,str,fret,reader.hasAltered,reader.hasAccidentals}})};b,e:=json.Marshal(out);if e!=nil{t.Fatal(e)};if e=os.WriteFile(filepath.Join(root,"compat/musicxml/note.json"),b,0644);e!=nil{t.Fatal(e)}}
